// Bricks: collision + bounce + score + drawing, all in one place.
// `bounced` guards the neighbour rule (#1): marking the brick dead and
// resolving the bounce exactly once per pass, so two overlapping bricks the
// same frame cannot cancel each other's flip out.
let bounced = false;
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  if (collides(state.ball, brick)) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    // Bounce the ball off the face it hit and push it out of the brick (#1).
    if (!bounced) {
      resolveBrickHit(state.ball, brick);
      bounced = true;
    }
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

